<?php
require __DIR__.'/../app/bootstrap.php';$admin=require_admin();$status=(string)($_GET['status']??'');$q=trim((string)($_GET['q']??''));$statuses=['pending','confirmed','shipping','completed','cancelled'];$where=[];$params=[];
if(in_array($status,$statuses,true)){$where[]='status=?';$params[]=$status;}
if($q!==''){$where[]='(order_code LIKE ? OR customer_name LIKE ? OR customer_phone LIKE ?)';$params[]='%'.$q.'%';$params[]='%'.$q.'%';$params[]='%'.$q.'%';}
$orders=all('SELECT * FROM orders'.($where?' WHERE '.implode(' AND ',$where):'').' ORDER BY id DESC LIMIT 300',$params);
$admin_title='Quản lý đơn hàng';$admin_menu='orders';require __DIR__.'/partials/header.php';
?>
<div class="admin-panel"><div class="admin-toolbar"><form method="get" action="<?= url('admin/orders.php') ?>"><input type="search" name="q" value="<?= e($q) ?>" placeholder="Tìm mã đơn, tên, SĐT..."><select name="status"><option value="">Mọi trạng thái</option><?php foreach($statuses as $s):?><option value="<?= e($s) ?>" <?= $status===$s?'selected':'' ?>><?= e(format_order_status($s)) ?></option><?php endforeach;?></select><button class="btn btn-outline" type="submit">Lọc</button></form><span class="hint"><?= count($orders) ?> đơn hàng</span></div><table class="admin-table"><thead><tr><th>Mã đơn</th><th>Khách hàng</th><th>Ngày đặt</th><th>Giá trị</th><th>Thanh toán</th><th>Trạng thái</th><th></th></tr></thead><tbody><?php foreach($orders as $o):?><tr><td><strong><?= e($o['order_code']) ?></strong></td><td><?= e($o['customer_name']) ?><br><small><?= e($o['customer_phone']) ?></small></td><td><?= date('d/m/Y H:i',strtotime($o['created_at'])) ?></td><td><?= money($o['total']) ?></td><td><?= $o['payment_method']==='cod'?'COD':'Chuyển khoản' ?><br><small><?= $o['payment_status']==='paid'?'Đã trả':'Chưa trả' ?></small></td><td><span class="status <?= e($o['status']) ?>"><?= e(format_order_status($o['status'])) ?></span></td><td><div class="admin-actions"><a href="<?= url('admin/order_detail.php?id='.$o['id']) ?>">Chi tiết</a></div></td></tr><?php endforeach;?></tbody></table><?php if(!$orders):?><p class="admin-empty">Chưa có đơn hàng phù hợp.</p><?php endif;?></div>
<?php require __DIR__.'/partials/footer.php';?>
